/** Arbitrary-precision rational number with a bigint numerator and denominator, always normalized. */
export class Rational {
  static readonly ZERO = new Rational(0n);
  static readonly ONE = new Rational(1n);

  readonly n: bigint; // numerator, sign carried here
  readonly d: bigint; // denominator, always positive

  constructor(n: bigint | number, d: bigint | number = 1n) {
    n = BigInt(n);
    d = BigInt(d);
    if (d === 0n) throw new Error("Rational: denominator must not be zero");
    if (d < 0n) {
      n = -n;
      d = -d;
    }
    const g = gcd(n < 0n ? -n : n, d); // gcd(0, d) = d, so 0 normalizes to 0/1
    this.n = n / g;
    this.d = d / g;
  }

  add(o: Rational): Rational {
    return new Rational(this.n * o.d + o.n * this.d, this.d * o.d);
  }

  sub(o: Rational): Rational {
    return new Rational(this.n * o.d - o.n * this.d, this.d * o.d);
  }

  mul(o: Rational): Rational {
    return new Rational(this.n * o.n, this.d * o.d);
  }

  div(o: Rational): Rational {
    if (o.isZero()) throw new Error("Rational: division by zero");
    return new Rational(this.n * o.d, this.d * o.n);
  }

  neg(): Rational {
    return new Rational(-this.n, this.d);
  }

  isZero(): boolean {
    return this.n === 0n;
  }

  isNegative(): boolean {
    return this.n < 0n;
  }

  eq(o: Rational): boolean {
    return this.n === o.n && this.d === o.d;
  }

  toString(): string {
    return this.d === 1n ? `${this.n}` : `${this.n}/${this.d}`;
  }
}

export function gcd(a: bigint, b: bigint): bigint {
  while (b !== 0n) {
    [a, b] = [b, a % b];
  }
  return a;
}

