import { Rational } from "./rational.js";

/**
 * Row-reduces the m x n rational matrix `A` (a copy is made) to reduced row
 * echelon form and returns { rref, pivotCols }.
 */
export function rref(A: Rational[][]): { rref: Rational[][]; pivotCols: number[] } {
  const M = A.map((row) => row.slice());
  const m = M.length;
  const n = m > 0 ? M[0].length : 0;
  const pivotCols: number[] = [];
  let row = 0;

  for (let col = 0; col < n && row < m; col++) {
    // Find a row with a nonzero entry in this column (no need for numeric pivoting over exact rationals).
    let pivot = -1;
    for (let i = row; i < m; i++) {
      if (!M[i][col].isZero()) {
        pivot = i;
        break;
      }
    }
    if (pivot === -1) continue;

    [M[row], M[pivot]] = [M[pivot], M[row]];
    const inv = M[row][col].div(Rational.ONE);
    for (let j = 0; j < n; j++) M[row][j] = M[row][j].mul(inv);

    for (let i = 0; i < m; i++) {
      if (i === row || M[i][col].isZero()) continue;
      const f = M[i][col];
      for (let j = 0; j < n; j++) {
        M[i][j] = M[i][j].sub(f.mul(M[row][j]));
      }
    }
    pivotCols.push(col);
    row++;
  }

  return { rref: M, pivotCols };
}

/**
 * Returns one nonzero vector x with A * x = 0, scaled so entries are rationals
 * with a common denominator of 1 preferred (caller rescales). Throws if the
 * null space is trivial or its dimension is not exactly 1.
 */
export function uniqueNullspaceVector(A: Rational[][]): Rational[] {
  const m = A.length;
  const n = m > 0 ? A[0].length : 0;
  if (n === 0) throw new Error("Cannot balance an equation with no chemical species");

  const { rref: R, pivotCols } = rref(A);
  const freeCols: number[] = [];
  for (let c = 0; c < n; c++) if (!pivotCols.includes(c)) freeCols.push(c);

  if (freeCols.length === 0) {
    throw new Error(
      "Equation cannot be balanced: the only solution of the element-conservation system is the trivial all-zero vector " +
        "(the species are linearly independent), i.e. no reaction conserving every element exists"
    );
  }
  if (freeCols.length > 1) {
    throw new Error(
      `Equation is underdetermined: the null space has dimension ${freeCols.length}, ` +
        "so coefficients are not unique — the equation likely contains independent sub-reactions"
    );
  }

  const free = freeCols[0];
  const x: Rational[] = Array.from({ length: n }, () => Rational.ZERO);
  x[free] = Rational.ONE;

  for (let i = pivotCols.length - 1; i >= 0; i--) {
    const c = pivotCols[i];
    let s = Rational.ZERO;
    for (let j = c + 1; j < n; j++) s = s.add(R[i][j].mul(x[j]));
    x[c] = s.neg();
  }

  return x;
}

