/**
 * Parses a chemical formula such as "Ca(OH)2", "Fe2(SO4)3" or "H2O" into a
 * map of element symbol -> atom count. Supports arbitrarily nested parentheses.
 */
export function parseFormula(formula: string): Map<string, bigint> {
  const src = formula.replace(/\s+/g, "");
  let pos = 0;

  function fail(msg: string): never {
    throw new Error(`Invalid formula "${formula}" at position ${pos + 1}: ${msg}`);
  }

  // group := (element count | '(' group ')' count)+
  function parseGroup(depth: number): Map<string, bigint> {
    const counts = new Map<string, bigint>();
    while (pos < src.length) {
      const ch = src[pos];
      if (ch === "(") {
        pos++;
        const inner = parseGroup(depth + 1);
        if (pos >= src.length || src[pos] !== ")") fail("expected ')'");
        pos++;
        const mult = parseCount();
        merge(counts, inner, mult);
      } else if (ch === ")") {
        if (depth === 0) fail("unmatched ')'");
        return counts;
      } else if (/[A-Z]/.test(ch)) {
        let sym = ch;
        pos++;
        while (pos < src.length && /[a-z]/.test(src[pos])) sym += src[pos++];
        const mult = parseCount();
        bump(counts, sym, mult);
      } else {
        fail(`unexpected character '${ch}'`);
      }
    }
    return counts;
  }

  function parseCount(): bigint {
    let num = "";
    while (pos < src.length && /[0-9]/.test(src[pos])) num += src[pos++];
    return num === "" ? 1n : BigInt(num);
  }

  function bump(counts: Map<string, bigint>, sym: string, mult: bigint): void {
    counts.set(sym, (counts.get(sym) ?? 0n) + mult);
  }

  function merge(into: Map<string, bigint>, from: Map<string, bigint>, mult: bigint): void {
    for (const [sym, c] of from) bump(into, sym, c * mult);
  }

  const result = parseGroup(0);
  if (pos < src.length) fail("unmatched ')'");
  if (result.size === 0) throw new Error(`Invalid formula "${formula}": no elements found`);
  return result;
}

