import { Rational, gcd as gcdBig } from "./rational.js";
import { uniqueNullspaceVector } from "./gauss.js";
import { parseFormula } from "./formula.js";

/**
 * Balances a chemical equation of the form
 *   "A + B(C)2 + ... -> X + Y"
 * and returns the minimal positive integer coefficient vector, one entry per
 * species in order of appearance (reactants first, then products).
 *
 * Method: build the element-conservation matrix A (rows = elements,
 * columns = species; products negated), solve A x = 0 exactly over the
 * rationals with Gaussian elimination, then scale the unique (up to sign)
 * null-space vector to coprime integers with an overall positive sign.
 */
export function balance(equation: string): number[] {
  const sides = equation.split("->");
  if (sides.length !== 2) {
    throw new Error(
      `Invalid equation "${equation}": expected exactly one "->" separating reactants and products`
    );
  }
  const reactantNames = splitSpecies(sides[0], equation);
  const productNames = splitSpecies(sides[1], equation);
  if (reactantNames.length === 0 || productNames.length === 0) {
    throw new Error(`Invalid equation "${equation}": both sides must contain at least one species`);
  }

  const names = [...reactantNames, ...productNames];
  const formulas = names.map((name) => parseFormula(name));

  // Collect all elements in stable order of first appearance.
  const elements: string[] = [];
  for (const f of formulas) for (const sym of f.keys()) if (!elements.includes(sym)) elements.push(sym);

  // Matrix: rows = elements, cols = species; products get negative coefficients.
  const A: Rational[][] = elements.map((sym) =>
    formulas.map((f, j) => {
      const c = f.get(sym) ?? 0n;
      return new Rational(j < reactantNames.length ? c : -c);
    })
  );

  const x = uniqueNullspaceVector(A);

  // Scale to integers: multiply by LCM of denominators, then divide by GCD of numerators.
  let lcm = 1n;
  for (const r of x) lcm = lcm * r.d / gcdBig(lcm, r.d);
  const ints = x.map((r) => r.n * (lcm / r.d));
  let g = 0n;
  for (const v of ints) g = gcdBig(g < 0n ? -g : g, v < 0n ? -v : v); // gcd(0,0)=0 handled below
  if (g > 1n) for (let i = 0; i < ints.length; i++) ints[i] /= g;

  if (ints.some((v) => v === 0n)) {
    throw new Error(
      `Equation "${equation}" cannot be balanced: some species would need coefficient 0`
    );
  }

  // Normalize overall sign so every coefficient is positive.
  const negativeCount = ints.filter((v) => v < 0n).length;
  const allNegative = ints.every((v) => v < 0n);
  if (!(negativeCount === 0 || allNegative)) {
    throw new Error(
      `Equation "${equation}" cannot be balanced consistently: the conservation solution has ` +
        "mixed signs, meaning atoms would have to be created or destroyed"
    );
  }
  const out = ints.map((v) => Number(allNegative ? -v : v));
  if (!out.every((c) => Number.isSafeInteger(c))) {
    throw new Error(`Balanced coefficients for "${equation}" exceed the safe integer range`);
  }
  return out;
}

function splitSpecies(side: string, equation: string): string[] {
  return side
    .split("+")
    .map((s) => s.trim())
    .map((s) => {
      if (s === "") throw new Error(`Invalid equation "${equation}": empty species next to "+"`);
      return s;
    });
}

