import { describe, it, expect } from "vitest";
import { balance } from "../src/balance.js";
import { gcd } from "../src/rational.js";

function assertCoprime(coeffs: number[]): void {
  const g = coeffs.reduce((acc, c) => gcd(BigInt(acc), BigInt(c)), 0n);
  expect(g, `coefficients [${coeffs}] should be coprime, got gcd=${g}`).toBe(1n);
}

describe("balance", () => {
  const cases: Array<[string, number[]]> = [
    ["C2H6 + O2 -> CO2 + H2O", [2, 7, 4, 6]],
    ["P4 + O2 -> P2O5", [1, 5, 2]],
    ["Fe + O2 -> Fe2O3", [4, 3, 2]],
  ];

  for (const [eq, expected] of cases) {
    it(`balances ${eq}`, () => {
      expect(balance(eq)).toEqual(expected);
      assertCoprime(balance(eq));
    });
  }

  it("handles nested parentheses", () => {
    // Ca(OH)2 + H3PO4 -> Ca3(PO4)2 + H2O
    const coeffs = balance("Ca(OH)2 + H3PO4 -> Ca3(PO4)2 + H2O");
    expect(coeffs).toEqual([3, 2, 1, 6]);
    assertCoprime(coeffs);
  });

  it("handles deeply nested parentheses", () => {
    // KMnO4 + HCl -> KCl + MnCl2 + H2O + Cl2
    expect(balance("KMnO4 + HCl -> KCl + MnCl2 + H2O + Cl2")).toEqual([2, 16, 2, 2, 8, 5]);
  });

  it("throws a descriptive error for an unbalanceable equation", () => {
    expect(() => balance("H2O -> H2O2")).toThrowError(
      /cannot be balanced.*trivial/i
    );
  });

  it("throws on malformed equations", () => {
    expect(() => balance("H2O = H2O")).toThrowError(/->/);
    expect(() => balance("H2 + -> H2O")).toThrowError(/empty species/);
    expect(() => balance("Hx + O2 -> H2O")).toThrowError(/unexpected character 'x'/);
  });
});

